// Musical pulse is a quarter note in simple meter, a dotted quarter in compound.
export const METERS={'2/4':{beats:2,division:2},'3/4':{beats:3,division:2},'4/4':{beats:4,division:2},'6/8':{beats:2,division:3},'9/8':{beats:3,division:3},'12/8':{beats:4,division:3}};
export const defaultRhythm=()=>({enabled:false,bpm:120,meter:'4/4',offset:0,swing:2/3,snap:false,sections:[]});
const range=(v,a,b,label)=>{v=Number(v);if(!Number.isFinite(v)||v<a||v>b)throw new Error(label+' is out of range.');return v;};
const settings=s=>{if(!METERS[s.meter])throw new Error('Choose a supported meter.');return {bpm:range(s.bpm,30,300,'Tempo'),meter:s.meter,swing:range(s.swing,.5,.75,'Swing')};};
export function validateRhythm(raw){const r={...defaultRhythm(),...raw};if(!Array.isArray(r.sections)||r.sections.length>200)throw new Error('Use up to 200 tempo sections.');const ids=new Set();const sections=r.sections.map(s=>{if(!s||typeof s.id!=='string'||!s.id||ids.has(s.id))throw new Error('Invalid tempo section.');ids.add(s.id);return {...settings(s),id:s.id,name:String(s.name||'Section').slice(0,40),at:range(s.at,0,86400,'Section time')};}).sort((a,b)=>a.at-b.at);for(let i=1;i<sections.length;i++)if(sections[i].at-sections[i-1].at<.009)throw new Error('Keep tempo sections at least 0.009 seconds apart.');return {...settings(r),enabled:!!r.enabled,snap:!!r.snap,offset:range(r.offset,0,86400,'First beat'),sections};}
export function rhythmAt(p,at){const r=p.rhythm||defaultRhythm();let section={id:'',name:'Main tempo',at:r.offset,bpm:r.bpm,meter:r.meter,swing:r.swing},end=Infinity;for(const s of r.sections){if(s.at<=at+1e-8)section=s;else{end=s.at;break;}}return {...section,end,beat:60/section.bpm,...METERS[section.meter]};}
export function beatGrid(p,from,to){if(!p.rhythm?.enabled||to<from)return [];const out=[],r=p.rhythm,parts=[{id:'',name:'Main tempo',at:r.offset,bpm:r.bpm,meter:r.meter,swing:r.swing},...r.sections];for(let i=0;i<parts.length;i++){const s=parts[i],end=parts[i+1]?.at??Infinity,lower=Math.max(from,i?s.at:-Infinity),upper=Math.min(to,end-1e-7),beat=60/s.bpm,meter=METERS[s.meter];if(upper<lower)continue;const first=Math.ceil((lower-s.at)/beat-1e-8),last=Math.floor((upper-s.at)/beat+1e-8);for(let n=first;n<=last&&out.length<5000;n++){const pulse=((n%meter.beats)+meter.beats)%meter.beats;out.push({at:s.at+n*beat,beat,number:pulse+1,bar:Math.floor(n/meter.beats)+1,downbeat:pulse===0,division:meter.division,swing:s.swing,section:s.id});}}return out;}
export function snapToBeat(p,at){if(!p.rhythm?.enabled||!p.rhythm.snap)return at;const candidates=beatGrid(p,Math.max(p.trimIn,at-2.1),Math.min(p.trimOut-.009,at+2.1));if(!candidates.length)return at;return candidates.reduce((best,b)=>Math.abs(b.at-at)<Math.abs(best-at)?b.at:best,candidates[0].at);}
export function tapEstimate(taps){if(taps.length<3)return null;const intervals=taps.slice(1).map((t,i)=>t-taps[i]).filter(t=>t>=.2&&t<=2);if(intervals.length<2)return null;const sorted=[...intervals].sort((a,b)=>a-b),median=sorted[Math.floor(sorted.length/2)],good=intervals.filter(t=>Math.abs(t-median)<median*.2);if(good.length<2)return null;return Math.round(600/(good.reduce((a,b)=>a+b,0)/good.length))/10;}
